import fs from "node:fs";
import path from "node:path";
import { describe, it, expect } from "vitest";
import config from "../../playwright.config.js";
import {
  DEMO_PORT,
  SCREENSHOT_NAMES,
  SCREENSHOT_VIEWS,
  assertDemoTarget,
  parseScreenshotManifest,
  readDemoCredentials,
} from "../e2e/support/demo-capture.js";

// Feature 012, FR-013 to FR-016 and FR-015a. The screenshots are generated by hand from the running demo and reviewed
// by the owner image by image; these checks pin the file set, the gate and the isolation rules of the capture spec.

const repoRoot = path.resolve(__dirname, "../../..");
const imagesDir = path.join(repoRoot, "docs", "images");
const specSource = fs.readFileSync(path.resolve(__dirname, "../e2e/screenshots.spec.ts"), "utf8");

function patterns(value: string | RegExp | (string | RegExp)[] | undefined): string[] {
  if (value === undefined) {
    return [];
  }
  return (Array.isArray(value) ? value : [value]).map((item) => String(item));
}

const manifest = parseScreenshotManifest(fs.readFileSync(path.join(imagesDir, "manifest.json"), "utf8"));

describe("docs/images manifest", () => {
  it("lists exactly the seven views in light and dark, fourteen files", () => {
    expect(SCREENSHOT_VIEWS).toEqual(["insights", "insights-drilldown", "postings-list", "posting-detail", "application-timeline", "company", "note"]);
    expect(SCREENSHOT_NAMES).toHaveLength(14);
    expect([...manifest.images].sort()).toEqual([...SCREENSHOT_NAMES].sort());
  });

  it("names the README hero image explicitly: the Insights view, light with a dark variant", () => {
    expect(manifest.hero.image).toEqual({ view: "insights", light: "insights-light.png", dark: "insights-dark.png" });
    expect(manifest.images).toContain(manifest.hero.image.light);
    expect(manifest.images).toContain(manifest.hero.image.dark);
  });

  it("names the hero records explicitly (DemoDatasetTests checks them against the seed's constants)", () => {
    expect(manifest.hero.records).toEqual({
      company: "Harborlight Systems",
      posting: "Head of Software Development",
      note: "Compensation research method",
      drilldown: "interviewed",
    });
  });

  it("the drill-down view follows the Insights stage link and checks the list against the link's count", () => {
    expect(specSource).toContain('[data-role="stage"][data-lens="${');
    expect(specSource).toMatch(/expect\(page\.locator\("tbody tr"\)\)\.toHaveCount\(/);
    expect(specSource).toMatch(/lens=/);
  });

  it("the Insights view ends on a section boundary instead of a fixed pixel cut", () => {
    expect(specSource).toContain("sectionBoundary");
  });

  it("the capture spec takes its hero records from the manifest, not from its own literals", () => {
    expect(specSource).toContain("parseScreenshotManifest(");
    expect(specSource).not.toContain('"Harborlight Systems"');
    expect(specSource).not.toContain('"Compensation research method"');
  });

  it("holds no file that the manifest does not list (images or temporary placeholders)", () => {
    const allowed = new Set([...manifest.images, ...(manifest.temporary ?? []).map((t) => t.file), "manifest.json"]);
    const unlisted = fs.readdirSync(imagesDir).filter((f) => !allowed.has(f));
    expect(unlisted, `unlisted files in docs/images: ${unlisted.join(", ")}`).toEqual([]);
  });

  it("keeps the placeholder only until every real image exists", () => {
    const present = manifest.images.filter((f) => fs.existsSync(path.join(imagesDir, f)));
    const placeholders = (manifest.temporary ?? []).filter((t) => fs.existsSync(path.join(imagesDir, t.file)));
    if (present.length === manifest.images.length) {
      expect(placeholders.map((p) => p.file), "all images exist: delete the placeholder and its manifest entry").toEqual([]);
      expect(manifest.temporary ?? []).toEqual([]);
    } else {
      expect(placeholders.length, "images are missing, so the placeholder must still exist").toBeGreaterThan(0);
    }
  });

  it("every manifest image that exists is a PNG with no text metadata chunks", () => {
    for (const name of manifest.images.filter((f) => fs.existsSync(path.join(imagesDir, f)))) {
      const bytes = fs.readFileSync(path.join(imagesDir, name));
      expect(bytes.subarray(0, 8).toString("hex"), name).toBe("89504e470d0a1a0a");
      let pos = 8;
      const chunks: string[] = [];
      while (pos + 8 <= bytes.length) {
        const length = bytes.readUInt32BE(pos);
        chunks.push(bytes.subarray(pos + 4, pos + 8).toString("ascii"));
        pos += 12 + length;
      }
      expect(chunks.filter((c) => ["tEXt", "zTXt", "iTXt", "eXIf"].includes(c)), `${name} carries metadata chunks`).toEqual([]);
    }
  });
});

describe("capture target guard", () => {
  it("accepts only the demo web origin", () => {
    expect(() => assertDemoTarget(`https://localhost:${DEMO_PORT}`)).not.toThrow();
    expect(() => assertDemoTarget(`https://web.localhost:${DEMO_PORT}/`)).not.toThrow();
  });

  it.each([
    "https://localhost:5003", // the real stack's web port
    "https://localhost:5001",
    "https://localhost:5002",
    "http://localhost:5103", // not https
    "https://example.com:5103",
    "https://127.0.0.1:5103",
    "https://localhost.evil.example:5103",
    "https://evil.example/localhost:5103",
    "not a url",
    "",
  ])("refuses %s", (target) => {
    expect(() => assertDemoTarget(target)).toThrow(/demo/i);
  });
});

describe("credentials come from the environment", () => {
  it("reads the three variables and names the missing ones without echoing values", () => {
    expect(readDemoCredentials({ ROLERADAR_DEMO_USERNAME: "u", ROLERADAR_DEMO_PASSWORD: "p", ROLERADAR_DEMO_TOTP_SECRET: "S" })).toEqual({
      username: "u",
      password: "p",
      totpSecret: "S",
    });
    expect(() => readDemoCredentials({ ROLERADAR_DEMO_USERNAME: "u", ROLERADAR_DEMO_PASSWORD: "super-secret-value" })).toThrow(/ROLERADAR_DEMO_TOTP_SECRET/);
    try {
      readDemoCredentials({ ROLERADAR_DEMO_USERNAME: "u", ROLERADAR_DEMO_PASSWORD: "super-secret-value" });
    } catch (error) {
      expect(String(error)).not.toContain("super-secret-value");
    }
  });
});

describe("the capture spec", () => {
  it("is skipped with a reason unless ROLERADAR_SCREENSHOT_DIR is set", () => {
    expect(specSource).toMatch(/test\.skip\(\s*!SCREENSHOT_DIR/);
    expect(specSource).toContain("ROLERADAR_SCREENSHOT_DIR");
  });

  it("reads its target and credentials from the environment, refuses a non-demo target and writes nothing else", () => {
    expect(specSource).toContain("ROLERADAR_DEMO_URL");
    expect(specSource).toContain("assertDemoTarget(");
    expect(specSource).toContain("readDemoCredentials(");
    expect(specSource).not.toMatch(/writeFile|appendFile|localStorage\.setItem\(\s*["'](pass|secret)/i);
  });

  it("runs only in the chromium project, which ignores HTTPS errors (self-signed demo certificates)", () => {
    expect(config.use?.ignoreHTTPSErrors).toBe(true);
    const chromium = (config.projects ?? []).find((p) => p.name === "chromium");
    expect(chromium).toBeDefined();
    expect(patterns(chromium?.testIgnore).some((p) => p.includes("screenshots"))).toBe(false);
    const realStack = (config.projects ?? []).find((p) => p.name === "real-stack");
    expect(patterns(realStack?.testMatch).join()).not.toContain("screenshots");
  });
});
